export async function writeAtomicDestination(handle, data, beforeWrite, assertBeforeMutation, onWriting) {
    if (beforeWrite)
        await beforeWrite();
    assertBeforeMutation?.();
    await handle.truncate(0);
    onWriting?.();
    let written = 0;
    while (written < data.length) {
        if (beforeWrite)
            await beforeWrite();
        assertBeforeMutation?.();
        const result = await handle.write(data, written, data.length - written, written);
        if (result.bytesWritten === 0)
            throw new Error("Copy fallback write made no progress");
        written += result.bytesWritten;
    }
    if (beforeWrite)
        await beforeWrite();
    assertBeforeMutation?.();
    await handle.truncate(data.length);
}
export function writeAtomicDestinationSync(fsModule, fd, data, beforeWrite, onWriting) {
    beforeWrite?.();
    fsModule.ftruncateSync(fd, 0);
    onWriting?.();
    let written = 0;
    while (written < data.length) {
        beforeWrite?.();
        const bytesWritten = fsModule.writeSync(fd, data, written, data.length - written, written);
        if (bytesWritten === 0)
            throw new Error("Copy fallback write made no progress");
        written += bytesWritten;
    }
    beforeWrite?.();
    fsModule.ftruncateSync(fd, data.length);
}
